use linguini_cldr::{
    compiled_number_formatting, NumberAffix, NumberFormatData, NumberPadding,
    NumberPaddingPosition, NumberPattern,
};

pub struct OptionalIntegerCase {
    pub name: &'static str,
    pub pattern: &'static str,
    pub locale: &'static str,
    pub min_integer: u8,
    pub min_fraction: u8,
    pub max_fraction: u8,
    pub decimal_separator_always: bool,
    pub group: Option<u8>,
    pub scale: u16,
    pub prefix: &'static str,
    pub suffix: &'static str,
    pub padding: Option<NumberPadding>,
    pub samples: &'static [(&'static str, &'static str)],
}

impl OptionalIntegerCase {
    pub fn formatting(&self) -> (NumberFormatData, NumberPattern) {
        let numbers = compiled_number_formatting(self.locale).unwrap();
        let mut pattern = numbers.decimal_pattern;
        let part = &mut pattern.positive;
        part.prefix = NumberAffix::Literal(self.prefix);
        part.suffix = NumberAffix::Literal(self.suffix);
        part.min_integer_digits = self.min_integer;
        part.min_fraction_digits = self.min_fraction;
        part.max_fraction_digits = self.max_fraction;
        part.decimal_separator_always = self.decimal_separator_always;
        part.primary_group_size = self.group;
        part.secondary_group_size = None;
        part.scale = self.scale;
        part.padding = self.padding;
        pattern.negative = None;
        (numbers, pattern)
    }
}

